mapper.select:
SELECT t_sprinkler.*
FROM t_sprinkler

    deleted_flag = #{queryForm.deletedFlag}

        AND INSTR(purchase_date_contract_number,#{queryForm.purchaseDateContractNumber})


        AND INSTR(sprinkler_model,#{queryForm.sprinklerModel})


        AND INSTR(sprinkler_serial,#{queryForm.sprinklerSerial})


        AND DATE_FORMAT(shipping_date, '%Y-%m-%d') >= #{queryForm.shippingDateStartTime}


        AND DATE_FORMAT(shipping_date, '%Y-%m-%d') <= #{queryForm.shippingDateEndTime}


        AND DATE_FORMAT(warehouse_date, '%Y-%m-%d') >= #{queryForm.warehouseDateStartTime}


        AND DATE_FORMAT(warehouse_date, '%Y-%m-%d') <= #{queryForm.warehouseDateEndTime}


        AND DATE_FORMAT(allocate_date, '%Y-%m-%d') >= #{queryForm.allocateDateStartTime}


        AND DATE_FORMAT(allocate_date, '%Y-%m-%d') <= #{queryForm.allocateDateEndTime}


        AND INSTR(allocate_user,#{queryForm.allocateUser})


        AND INSTR(allocate_purpose,#{queryForm.allocatePurpose})


        AND INSTR(allocate_position,#{queryForm.allocatePosition})


        AND INSTR(history,#{queryForm.history})


        AND status = #{queryForm.status}


        AND is_new = #{queryForm.isNew}


        AND INSTR(sprinkler_detail,#{queryForm.sprinklerDetail})


        AND disabled_flag = #{queryForm.disabledFlag}



    ORDER BY create_time DESC


    ORDER BY




                CASE WHEN LEFT(allocate_position, 2) = 'LK' THEN 7
                ELSE FIELD(LEFT(allocate_position, 1), 'K','C','M','Y','O','B','R')
                END,
                CAST(REGEXP_REPLACE(allocate_position, '[^0-9]', '') AS UNSIGNED) ${sortItem.isAsc ? 'ASC' : 'DESC'}



                CASE WHEN sprinkler_serial REGEXP '^\\w{6}-\\d{2}$' THEN 0 ELSE 1 END ${sortItem.isAsc ? 'ASC' : 'DESC'},
                SUBSTRING(sprinkler_serial, 1, 6) ${sortItem.isAsc ? 'ASC' : 'DESC'},
                CAST(SUBSTRING(sprinkler_serial, 8, 2) AS UNSIGNED) ${sortItem.isAsc ? 'ASC' : 'DESC'}




                `${sortItem.column}` ${sortItem.isAsc ? 'ASC' : 'DESC'}

SELECT *
FROM t_sprinkler
WHERE sprinkler_serial = #{sprinklerSerial}
AND deleted_flag = #{deletedFlag}

    AND sprinkler_id != #{excludeSprinklerId}

SELECT t_sprinkler.*
FROM t_sprinkler

    deleted_flag = #{queryForm.deletedFlag}

        AND INSTR(purchase_date_contract_number,#{queryForm.purchaseDateContractNumber})


        AND INSTR(sprinkler_model,#{queryForm.sprinklerModel})


        AND INSTR(sprinkler_serial,#{queryForm.sprinklerSerial})


        AND DATE_FORMAT(shipping_date, '%Y-%m-%d') >= #{queryForm.shippingDateStartTime}


        AND DATE_FORMAT(shipping_date, '%Y-%m-%d') <= #{queryForm.shippingDateEndTime}


        AND DATE_FORMAT(warehouse_date, '%Y-%m-%d') >= #{queryForm.warehouseDateStartTime}


        AND DATE_FORMAT(warehouse_date, '%Y-%m-%d') <= #{queryForm.warehouseDateEndTime}


        AND DATE_FORMAT(allocate_date, '%Y-%m-%d') >= #{queryForm.allocateDateStartTime}


        AND DATE_FORMAT(allocate_date, '%Y-%m-%d') <= #{queryForm.allocateDateEndTime}


        AND INSTR(allocate_user,#{queryForm.allocateUser})


        AND INSTR(allocate_purpose,#{queryForm.allocatePurpose})


        AND INSTR(allocate_position,#{queryForm.allocatePosition})


        AND INSTR(history,#{queryForm.history})


        AND status = #{queryForm.status}


        AND is_new = #{queryForm.isNew}


        AND INSTR(sprinkler_detail,#{queryForm.sprinklerDetail})


        AND disabled_flag = #{queryForm.disabledFlag}



    ORDER BY create_time DESC

